sys_script_fix.script:
// Add your code here

var impSet = new GlideRecord("x_g_dh5_appointed_capstone_bodega_data");
impSet.get("0e40c8a01b5c66d0065762cae54bcb94");

var currentPosition = impSet.u_capposid;

var emailAddress = impSet.u_email.toString();

//Check to verify is assigned to actual user
if (!gs.nil(emailAddress) && emailAddress !== "Vacant") {

    //Query for other records for user in Import Set
    var isetGR = new GlideRecord('x_g_dh5_appointed_capstone_bodega_data');
    isetGR.addQuery("sys_import_set", impSet.sys_import_set);
    isetGR.addQuery("u_email", emailAddress);
    isetGR.query();

    if (isetGR.next()) {

        //If impSet.u_end_date is null, user is still an active appointed position on the impSet record
        if (gs.nil(impSet.u_end_date)) {
            currentRetentionGroup(emailAddress);
        }

        //If user is no longer an active appointed position (on impSet or isetGR record), u_retention group is set to none
        else if (!gs.nil(impSet.u_end_date) && !gs.nil(isetGR.u_end_date)) {
            retiredUser(emailAddress);
        }
    }

    //If duplicate is not found and user is no longer an active appointed position
    else if (!gs.nil(impSet.u_end_date)) {
        retiredUser(emailAddress);
    }

    //If duplicate is not found and IS an active appointed position
    else if (gs.nil(impSet.u_end_date)) {
        currentRetentionGroup(emailAddress);
    }

}

function userQuery(userEmail) {
    var capstoneUser = new GlideRecord("sys_user");
    capstoneUser.addQuery("email", userEmail);
    //capstoneUser.addEncodedQuery('email=Erik.P.Breitzke@ice.dhs.gov');
    capstoneUser.query();

    if (capstoneUser.next()) {
        return capstoneUser;
    }
}

function currentRetentionGroup(userEmail) {
    var getUserRecord = this.userQuery(userEmail);
    getUserRecord.setValue("u_retention_group", currentPosition);
    getUserRecord.setWorkflow(false);
    getUserRecord.update();
}

function retiredUser(userEmail) {
    var getUserRecord = this.userQuery(userEmail);
    getUserRecord.setValue("u_retention_group", "");
    getUserRecord.setWorkflow(false);
    getUserRecord.update();
}
